+/**
+ * Merge two hooks objects with name-based task override.
+ * Structure: { type: { event: [tasks] } }
+ * Same-name task in override fully replaces base task.
+ * New-name tasks are appended after inherited tasks.
+ * Base tasks come first (global before project).
+ */
+function mergeHooks (base, override) {
+  if (!base || typeof base !== 'object') return override || {}
+  if (!override || typeof override !== 'object') return base || {}
+
+  const result = {}
+  const allTypes = new Set([...Object.keys(base), ...Object.keys(override)])
+
+  for (const type of allTypes) {
+    const baseEvents = base[type] || {}
+    const overrideEvents = override[type] || {}
+    result[type] = {}
+
+    const allEvents = new Set([...Object.keys(baseEvents), ...Object.keys(overrideEvents)])
+    for (const event of allEvents) {
+      const baseTasks = baseEvents[event] || []
+      const overrideTasks = overrideEvents[event] || []
+
+      if (overrideTasks.length === 0) {
+        result[type][event] = [...baseTasks]
+        continue
+      }
+
+      const overrideNames = new Set(overrideTasks.map(t => t.name))
+      // Start with base tasks, replacing same-name ones in place
+      const merged = baseTasks.map(t =>
+        overrideNames.has(t.name)
+          ? overrideTasks.find(ot => ot.name === t.name)
